import{_ as e,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"第五章：手写一个支持 import-export 的简易 JS 打包器","description":"好，咱们就按顺序继续 —— 进入 第五章：实现简易打包器（支持多模块打包成一个文件） ，模拟 Vite/Rollup 的打包过程。 🧰 ✅ 本章目标： 读取多个模块文件 分析模块依赖图 合并成一个 JS 文件 保持模块隔离 + 依赖顺序正确 🏗️ 一、项目结构 esbundler。","frontmatter":{"title":"第五章：手写一个支持 import-export 的简易 JS 打包器","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"好，咱们就按顺序继续 —— 进入 第五章：实现简易打包器（支持多模块打包成一个文件） ，模拟 Vite/Rollup 的打包过程。 🧰 ✅ 本章目标： 读取多个模块文件 分析模块依赖图 合并成一个 JS 文件 保持模块隔离 + 依赖顺序正确 🏗️ 一、项目结构 esbundler。","sidebarWeight":44,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/第五章：手写一个支持 import-export 的简易 JS 打包器.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第五章：手写一个支持 import-export 的简易 JS 打包器.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第五章：手写一个支持 import-export 的简易 JS 打包器.md"}'),n={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第五章：手写一个支持 import-export 的简易 JS 打包器.md"};function d(p,t,a,i,l,c){return o(),r("div",null,[...t[0]||(t[0]=[s('<div><h1 id="第五章-手写一个支持-import-export-的简易-js-打包器" tabindex="-1">第五章：手写一个支持 import-export 的简易 JS 打包器 <a class="header-anchor" href="#第五章-手写一个支持-import-export-的简易-js-打包器" aria-label="Permalink to &quot;第五章：手写一个支持 import-export 的简易 JS 打包器&quot;">​</a></h1><blockquote><p>本节目标：理解“第五章：手写一个支持 import-export 的简易 JS 打包器”的核心思路，并能把它用于实际开发或面试表达。 好，咱们就按顺序继续 —— 进入 <strong>第五章：实现简易打包器（支持多模块打包成一个文件）</strong>，模拟 Vite/Rollup 的打包过程。</p></blockquote><p><strong>🧰</strong> ✅ 本章目标：</p><ul><li>读取多个模块文件</li><li>分析模块依赖图</li><li>合并成一个 JS 文件</li><li>保持模块隔离 + 依赖顺序正确</li></ul><p><strong>🏗️</strong> <strong>一、项目结构</strong> esbundler/├── src/│ ├── main.mjs│ ├── a.mjs│ └── b.mjs├── bundler.js # ✅ 打包核心文件└── dist/bundle.js # ✅ 打包结果</p><p><strong>🧱</strong> <strong>二、模块代码示例</strong><strong>📄</strong> <strong>src/a.mjs</strong> export const msg = &#39;Hello from A&#39;; <strong>📄</strong> <strong>src/b.mjs</strong> import { msg } from &#39;./a.mjs&#39;;export const content = msg + &#39; and B&#39;; <strong>📄</strong> <strong>src/main.mjs</strong> import { content } from &#39;./b.mjs&#39;;console.log(content);</p><p><strong>🧠</strong> <strong>三、构建打包器 bundler.js（简易依赖图 + 模板合成）</strong><strong>📦</strong> <strong>安装依赖：</strong> npm install acorn</p><p><strong>📄</strong> <strong>bundler.js</strong> const fs = require(&#39;fs&#39;);const path = require(&#39;path&#39;);const acorn = require(&#39;acorn&#39;); const entry = &#39;./src/main.mjs&#39;;const output = &#39;./dist/bundle.js&#39;; let id = 0; // 分析模块：读取代码、找依赖、记录 idfunction parseModule(filePath) { const absPath = path.resolve(__dirname, filePath); const code = fs.readFileSync(absPath, &#39;utf-8&#39;); const ast = acorn.parse(code, { sourceType: &#39;module&#39;, ecmaVersion: &#39;latest&#39; }); const deps = []; ast.body.forEach(node =&gt; { if (node.type === &#39;ImportDeclaration&#39;) { deps.push(node.source.value); } }); return { id: id++, filePath, code, deps };} // 构建依赖图function buildGraph(entryPath) { const entryModule = parseModule(entryPath); const graph = [entryModule]; const visited = new Set([entryModule.filePath]); for (const mod of graph) { mod.mapping = {}; mod.deps.forEach(depRel =&gt; { const depAbs = path.resolve(path.dirname(mod.filePath), depRel); if (!visited.has(depAbs)) { const depMod = parseModule(depAbs); graph.push(depMod); visited.add(depAbs); mod.mapping[depRel] = depMod.id; } else { const existing = graph.find(m =&gt; path.resolve(m.filePath) === depAbs); mod.mapping[depRel] = existing.id; } }); } return graph;} // 转换成打包后代码function bundle(graph) { const modules = graph.map(mod =&gt; { return <code>${mod.id}: [ function(require, exports) { ${mod.code} }, ${JSON.stringify(mod.mapping)} ]</code>; }).join(&#39;,&#39;); return <code>(function(modules) { function require(id) { const [fn, mapping] = modules[id]; const exports = {}; function localRequire(name) { return require(mapping[name]); } fn(localRequire, exports); return exports; } require(0);})({${modules}})</code>;} const graph = buildGraph(entry);const result = bundle(graph);fs.writeFileSync(output, result, &#39;utf-8&#39;);console.log(&#39;✅ 打包完成：dist/bundle.js&#39;);</p><p><strong>🚀</strong> <strong>运行打包器</strong> node bundler.js</p><p><strong>✅</strong> <strong>执行打包结果</strong> node dist/bundle.js# 输出: Hello from A and B</p><p><strong>✅</strong> <strong>本章功能总结</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>能力</strong></td><td><strong>实现情况</strong></td></tr><tr><td>静态分析 import</td><td>✔ acorn</td></tr><tr><td>构建模块依赖图</td><td>✔</td></tr><tr><td>多模块合并输出</td><td>✔</td></tr><tr><td>模拟 require 加载器</td><td>✔</td></tr><tr><td>支持相对路径 import</td><td>✔</td></tr></tbody></table><p><strong>🔮</strong> <strong>下一章预告（第六章）</strong> 我们接下来可以继续进入： ✅ <strong>第六章：实现 Tree Shaking — 只打包实际使用的 export</strong> 例如： // a.mjsexport const used = 1;export const unused = 2; // b.mjsimport { used } from &#39;./a.mjs&#39;;console.log(used); Tree Shaking 会让 unused 不出现在打包代码中。</p><p>要继续进入第六章吗？我们马上搞起。 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const m=e(n,[["render",d]]);export{u as __pageData,m as default};
